package main

import (
	"bytes"
	"errors"
	"flag"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/printer"
	"go/token"
	"io"
	"log"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

const (
	versionString = "3.0.0-20260303205914-9926ea38658f"
	builtWith     = "go1.26.0"
	tagString     = "v3.0.0-20260303205914-9926ea38658f"
	commitString  = "n/a"
	sourceString  = "github.com/incu6us/goimports-reviser/v3"
)

type config struct {
	applyToGeneratedFiles bool
	companyPrefixes       string
	excludes              string
	filePath              string
	format                bool
	importsOrder          string
	listDiff              bool
	local                 string
	output                string
	projectName           string
	recursive             bool
	rmUnused              bool
	separateNamed         bool
	setAlias              bool
	setExitStatus         bool
	useCache              bool
	version               bool
	versionOnly           bool
}

type app struct {
	cfg             config
	order           []string
	orderSet        map[string]bool
	companyPrefixes []string
	excludes        []string
	resolvedNames   map[string]string
	changedAny      bool
	deprecatedUsed  bool
}

type targetKind int

const (
	targetFile targetKind = iota
	targetDir
	targetGlob
)

type targetInfo struct {
	kind targetKind
	root string
	arg  string
}

type fileResult struct {
	path      string
	original  []byte
	formatted []byte
	changed   bool
	skipped   bool
}

func main() {
	log.SetFlags(log.LstdFlags)

	cfg, usage, err := parseFlags(os.Args[1:])
	if err != nil {
		if errors.Is(err, flag.ErrHelp) {
			usage()
			os.Exit(0)
		}

		usage()
		os.Exit(2)
	}

	if cfg.versionOnly {
		fmt.Println(versionString)
		return
	}

	if cfg.version {
		fmt.Printf("version: %s\n", versionString)
		fmt.Printf("built with: %s\n", builtWith)
		fmt.Printf("tag: %s\n", tagString)
		fmt.Printf("commit: %s\n", commitString)
		fmt.Printf("source: %s\n", sourceString)
		return
	}

	paths := collectPaths(cfg)
	if len(paths) == 0 {
		usage()
		log.Printf("no file(s) or directory(ies) specified on input")
		os.Exit(1)
	}

	order, err := parseImportsOrder(cfg.importsOrder)
	if err != nil {
		usage()
		log.Printf("%v", err)
		os.Exit(1)
	}

	a := &app{
		cfg:             cfg,
		order:           order,
		orderSet:        make(map[string]bool, len(order)),
		companyPrefixes: splitComma(cfg.companyPrefixes),
		excludes:        splitComma(cfg.excludes),
		resolvedNames:   make(map[string]string),
	}
	for _, group := range order {
		a.orderSet[group] = true
	}

	log.Printf("Paths: [%s]", strings.Join(paths, " "))

	exitCode := a.run(paths, usage)
	os.Exit(exitCode)
}

func parseFlags(args []string) (config, func(), error) {
	var cfg config

	fs := flag.NewFlagSet(os.Args[0], flag.ContinueOnError)
	fs.SetOutput(os.Stderr)

	fs.BoolVar(&cfg.applyToGeneratedFiles, "apply-to-generated-files", false, "Apply imports sorting and formatting(if the option is set) to generated files. Generated file is a file with first comment which starts with comment '// Code generated'. Optional parameter.")
	fs.StringVar(&cfg.companyPrefixes, "company-prefixes", "", "Company package prefixes which will be placed after 3rd-party group by default(if defined). Values should be comma-separated. Optional parameters.")
	fs.StringVar(&cfg.excludes, "excludes", "", "Exclude files or dirs, example: '.git/,proto/*.go'.")
	fs.StringVar(&cfg.filePath, "file-path", "", "Deprecated. Put file name as an argument(last item) of command line.")
	fs.BoolVar(&cfg.format, "format", false, "Option will perform additional formatting. Optional parameter.")
	fs.StringVar(&cfg.importsOrder, "imports-order", "std,general,company,project", "Your imports groups can be sorted in your way. \n\tstd - std import group; \n\tgeneral - libs for general purpose; \n\tcompany - inter-org or your company libs(if you set '-company-prefixes'-option, then 4th group will be split separately. In other case, it will be the part of general purpose libs); \n\tproject - your local project dependencies;\n\tblanked - imports with \"_\" alias;\n\tdotted - imports with \".\" alias.\n\tOptional parameter.")
	fs.BoolVar(&cfg.listDiff, "list-diff", false, "Option will list files whose formatting differs from goimports-reviser. Optional parameter.")
	fs.StringVar(&cfg.local, "local", "", "Deprecated")
	fs.StringVar(&cfg.output, "output", "file", "Can be \"file\", \"write\" or \"stdout\". Whether to write the formatted content back to the file or to stdout. When \"write\" together with \"-list-diff\" will list the file name and write back to the file. Optional parameter.")
	fs.StringVar(&cfg.projectName, "project-name", "", "Your project name(ex.: github.com/incu6us/goimports-reviser). Optional parameter.")
	fs.BoolVar(&cfg.recursive, "recursive", false, "Apply rules recursively if target is a directory. In case of ./... execution will be recursively applied by default. Optional parameter.")
	fs.BoolVar(&cfg.rmUnused, "rm-unused", false, "Remove unused imports. Optional parameter.")
	fs.BoolVar(&cfg.separateNamed, "separate-named", false, "Option will separate named imports from the rest of the imports, per group. Optional parameter.")
	fs.BoolVar(&cfg.setAlias, "set-alias", false, "Set alias for versioned package names, like 'github.com/go-pg/pg/v9'. In this case import will be set as 'pg \"github.com/go-pg/pg/v9\"'. Optional parameter.")
	fs.BoolVar(&cfg.setExitStatus, "set-exit-status", false, "set the exit status to 1 if a change is needed/made. Optional parameter.")
	fs.BoolVar(&cfg.useCache, "use-cache", false, "Use cache to improve performance. Optional parameter.")
	fs.BoolVar(&cfg.version, "version", false, "Show version information")
	fs.BoolVar(&cfg.versionOnly, "version-only", false, "Show only the version string")

	usage := func() {
		fmt.Fprintf(os.Stderr, "Usage of %s:\n", os.Args[0])
		fs.PrintDefaults()
	}
	fs.Usage = usage

	err := fs.Parse(args)
	if err != nil {
		return config{}, usage, err
	}

	if cfg.filePath != "" {
		cfg.filePath = strings.TrimSpace(cfg.filePath)
	}
	if cfg.local != "" {
		cfg.local = strings.TrimSpace(cfg.local)
	}

	if remaining := fs.Args(); len(remaining) > 0 {
		cfg.filePath = strings.TrimSpace(strings.Join(append(strings.Fields(cfg.filePath), remaining...), " "))
	}

	return cfg, usage, nil
}

func collectPaths(cfg config) []string {
	var paths []string
	if cfg.filePath != "" {
		paths = append(paths, strings.Fields(cfg.filePath)...)
	}
	return paths
}

func parseImportsOrder(raw string) ([]string, error) {
	if raw == "" {
		raw = "std,general,company,project"
	}
	parts := splitComma(raw)
	if len(parts) == 0 {
		return []string{"std", "general", "company", "project"}, nil
	}
	if len(parts) < 4 {
		return nil, fmt.Errorf("use default at least 4 parameters to sort groups of your imports: %q", "std,general,company,project")
	}
	valid := map[string]bool{
		"std":     true,
		"general": true,
		"company": true,
		"project": true,
		"blanked": true,
		"dotted":  true,
	}
	for _, part := range parts {
		if !valid[part] {
			return nil, fmt.Errorf("unknown order group type: %q", part)
		}
	}
	return parts, nil
}

func splitComma(value string) []string {
	if value == "" {
		return nil
	}
	raw := strings.Split(value, ",")
	out := make([]string, 0, len(raw))
	for _, item := range raw {
		item = strings.TrimSpace(item)
		if item != "" {
			out = append(out, item)
		}
	}
	return out
}

func (a *app) run(paths []string, usage func()) int {
	var failed bool

	if a.cfg.local != "" || a.cfg.filePath != "" {
		a.deprecatedUsed = true
	}

	for _, p := range paths {
		log.Printf("Processing %s", p)

		info, err := a.prepareTarget(p)
		if err != nil {
			usage()
			log.Printf("Could not determine project name for path %s: %v", p, err)
			return 1
		}

		switch info.kind {
		case targetFile:
			if err := a.handleFileTarget(info); err != nil {
				failed = true
			}
		case targetDir, targetGlob:
			if err := a.handleDirectoryTarget(info); err != nil {
				failed = true
			}
		}
	}

	if a.deprecatedUsed {
		if a.cfg.local != "" {
			log.Printf("-local is deprecated and will be removed soon. Use -company-prefixes instead.")
		}
		if a.cfg.filePath != "" {
			log.Printf("-file-path is deprecated. Put file name(s) as last argument to the command(Example: goimports-reviser -rm-unused -set-alias -format goimports-reviser/main.go)")
		}
		log.Printf("All changes to file are applied, but command-line syntax should be fixed")
		return 1
	}

	if failed {
		return 1
	}
	if a.cfg.setExitStatus && a.changedAny {
		return 1
	}
	return 0
}

func (a *app) prepareTarget(arg string) (targetInfo, error) {
	if arg == "./..." {
		root, err := a.resolveProjectRoot(".")
		if err != nil {
			return targetInfo{}, err
		}
		return targetInfo{kind: targetGlob, root: ".", arg: arg}, a.ensureProjectName(root)
	}

	info, err := os.Stat(arg)
	if err == nil {
		if info.IsDir() {
			root, err := a.resolveProjectRoot(arg)
			if err != nil {
				return targetInfo{}, err
			}
			return targetInfo{kind: targetDir, root: arg, arg: arg}, a.ensureProjectName(root)
		}
		root, err := a.resolveProjectRoot(filepath.Dir(arg))
		if err != nil {
			return targetInfo{}, err
		}
		return targetInfo{kind: targetFile, root: filepath.Dir(arg), arg: arg}, a.ensureProjectName(root)
	}

	root, rootErr := a.resolveProjectRoot(filepath.Dir(arg))
	if rootErr != nil {
		return targetInfo{}, rootErr
	}
	return targetInfo{kind: targetFile, root: filepath.Dir(arg), arg: arg}, a.ensureProjectName(root)
}

func (a *app) ensureProjectName(root string) error {
	if a.cfg.projectName != "" {
		return nil
	}
	_, err := readModuleName(root)
	return err
}

func (a *app) resolveProjectRoot(start string) (string, error) {
	start = filepath.Clean(start)
	if start == "." {
		cwd, err := os.Getwd()
		if err != nil {
			return "", err
		}
		start = cwd
	}
	absStart, err := filepath.Abs(start)
	if err != nil {
		return "", err
	}

	cur := absStart
	for {
		if _, err := os.Stat(filepath.Join(cur, "go.mod")); err == nil {
			return cur, nil
		}

		parent := filepath.Dir(cur)
		if parent == cur {
			return "", fmt.Errorf("open go.mod: no such file or directory")
		}
		cur = parent
	}
}

func readModuleName(root string) (string, error) {
	data, err := os.ReadFile(filepath.Join(root, "go.mod"))
	if err != nil {
		return "", err
	}
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "module ") {
			return strings.TrimSpace(strings.TrimPrefix(line, "module ")), nil
		}
	}
	return "", fmt.Errorf("open go.mod: no such file or directory")
}

func (a *app) handleFileTarget(info targetInfo) error {
	result, err := a.processFile(info.arg, info.root)
	if err != nil {
		log.Printf("Failed to fix file: %v", err)
		return err
	}
	return a.emitFileResult(info, result)
}

func (a *app) handleDirectoryTarget(info targetInfo) error {
	files, err := a.collectFiles(info)
	if err != nil {
		if a.cfg.listDiff {
			log.Printf("Failed to find unformatted files %s: failed to walk dif: %v", info.arg, err)
		} else {
			log.Printf("Failed to fix file: %v", err)
		}
		return err
	}

	for _, file := range files {
		result, err := a.processFile(file, filepath.Dir(file))
		if err != nil {
			if a.cfg.listDiff {
				wrapped := fmt.Errorf("failed to fix %s: %w", mustAbs(file), err)
				log.Printf("Failed to find unformatted files %s: failed to walk dif: %v", info.arg, wrapped)
			} else {
				log.Printf("Failed to fix file: %v", err)
			}
			return err
		}
		if err := a.emitDirectoryResult(result); err != nil {
			return err
		}
	}

	return nil
}

func (a *app) collectFiles(info targetInfo) ([]string, error) {
	root := info.root
	if info.kind == targetGlob {
		root = "."
	}

	recursive := a.cfg.recursive || info.kind == targetGlob
	stat, err := os.Stat(root)
	if err != nil {
		return nil, err
	}
	if !stat.IsDir() {
		return []string{root}, nil
	}

	var files []string
	err = filepath.WalkDir(root, func(path string, d os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}

		if path == root {
			return nil
		}

		rel, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		rel = filepath.ToSlash(rel)

		if d.IsDir() {
			if a.isExcluded(rel + "/") {
				return filepath.SkipDir
			}
			if !recursive && filepath.Dir(rel) != "." && rel != "." {
				return filepath.SkipDir
			}
			return nil
		}

		if filepath.Ext(path) != ".go" {
			return nil
		}
		if !recursive && strings.Contains(rel, "/") {
			return nil
		}
		if a.isExcluded(rel) {
			return nil
		}

		files = append(files, path)
		return nil
	})
	if err != nil {
		return nil, err
	}

	sort.Strings(files)
	return files, nil
}

func (a *app) isExcluded(rel string) bool {
	if rel == "" {
		return false
	}
	base := filepath.Base(rel)
	for _, pattern := range a.excludes {
		if strings.HasSuffix(pattern, "/") {
			if strings.HasPrefix(rel, pattern) {
				return true
			}
			continue
		}
		if matched, _ := filepath.Match(pattern, rel); matched {
			return true
		}
		if matched, _ := filepath.Match(pattern, base); matched {
			return true
		}
		if rel == pattern || base == pattern {
			return true
		}
	}
	return false
}

func (a *app) processFile(path, workingDir string) (fileResult, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return fileResult{}, err
	}

	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, path, data, parser.ParseComments)
	if err != nil {
		return fileResult{}, fmt.Errorf("file has invalid Go source content, use -excludes flag to skip this file: %s", err)
	}

	projectName := a.cfg.projectName
	if projectName == "" {
		root, err := a.resolveProjectRoot(workingDir)
		if err != nil {
			return fileResult{}, err
		}
		projectName, err = readModuleName(root)
		if err != nil {
			return fileResult{}, err
		}
	}

	importDecls := collectImportDecls(file)
	if len(importDecls) == 0 {
		formatted, err := format.Source(data)
		if err != nil {
			return fileResult{}, err
		}
		return fileResult{
			path:      path,
			original:  data,
			formatted: formatted,
			changed:   !bytes.Equal(data, formatted),
		}, nil
	}

	if isGenerated(file) && !a.cfg.applyToGeneratedFiles {
		return fileResult{
			path:      path,
			original:  data,
			formatted: data,
			skipped:   true,
		}, nil
	}

	specs := collectImportSpecs(importDecls)
	if a.cfg.rmUnused || a.cfg.setAlias {
		if err := a.resolveImportNames(specs, workingDir); err != nil {
			return fileResult{}, fmt.Errorf("package has an errors")
		}
	}

	usedNames := scanUsedImportNames(file)
	newSpecs, err := a.rewriteImportSpecs(specs, usedNames, projectName, workingDir)
	if err != nil {
		return fileResult{}, err
	}

	block := a.renderImportBlock(fset, newSpecs)
	rewritten := replaceImportBlock(data, fset, importDecls, block)
	formatted, err := format.Source(rewritten)
	if err != nil {
		return fileResult{}, err
	}

	return fileResult{
		path:      path,
		original:  data,
		formatted: formatted,
		changed:   !bytes.Equal(data, formatted),
	}, nil
}

func collectImportDecls(file *ast.File) []*ast.GenDecl {
	var decls []*ast.GenDecl
	for _, decl := range file.Decls {
		gen, ok := decl.(*ast.GenDecl)
		if !ok || gen.Tok != token.IMPORT {
			continue
		}
		decls = append(decls, gen)
	}
	return decls
}

func collectImportSpecs(decls []*ast.GenDecl) []*ast.ImportSpec {
	var specs []*ast.ImportSpec
	for _, decl := range decls {
		for _, spec := range decl.Specs {
			importSpec, ok := spec.(*ast.ImportSpec)
			if ok {
				specs = append(specs, importSpec)
			}
		}
	}
	return specs
}

func isGenerated(file *ast.File) bool {
	for _, cg := range file.Comments {
		for _, c := range cg.List {
			text := strings.TrimSpace(c.Text)
			if strings.HasPrefix(text, "// Code generated") {
				return true
			}
			return false
		}
	}
	return false
}

func (a *app) resolveImportNames(specs []*ast.ImportSpec, workingDir string) error {
	var firstErr error
	for _, spec := range specs {
		path := strings.Trim(spec.Path.Value, `"`)
		if isStdImport(path) {
			continue
		}
		if _, ok := a.resolvedNames[path]; ok {
			continue
		}

		cmd := exec.Command("go", "list", "-f", "{{.Name}}", path)
		cmd.Dir = workingDir
		output, err := cmd.CombinedOutput()
		if err != nil {
			if len(output) > 0 {
				_, _ = os.Stderr.Write(output)
			}
			if firstErr == nil {
				firstErr = err
			}
			continue
		}
		a.resolvedNames[path] = strings.TrimSpace(string(output))
	}
	return firstErr
}

func scanUsedImportNames(file *ast.File) map[string]bool {
	used := make(map[string]bool)
	ast.Inspect(file, func(node ast.Node) bool {
		sel, ok := node.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		ident, ok := sel.X.(*ast.Ident)
		if !ok {
			return true
		}
		used[ident.Name] = true
		return true
	})
	return used
}

type importEntry struct {
	spec    *ast.ImportSpec
	group   string
	path    string
	explicit bool
}

func (a *app) rewriteImportSpecs(specs []*ast.ImportSpec, usedNames map[string]bool, projectName, workingDir string) ([]*ast.ImportSpec, error) {
	entries := make([]importEntry, 0, len(specs))
	for _, spec := range specs {
		path := strings.Trim(spec.Path.Value, `"`)
		alias := ""
		if spec.Name != nil {
			alias = spec.Name.Name
		}

		resolvedName := defaultImportName(path)
		if name, ok := a.resolvedNames[path]; ok && name != "" {
			resolvedName = name
		}

		if a.cfg.setAlias && spec.Name == nil {
			if aliasName, ok := versionAlias(path, resolvedName); ok {
				spec.Name = ast.NewIdent(aliasName)
				alias = aliasName
			}
		}

		if a.cfg.rmUnused {
			if alias == "_" || alias == "." {
				// Keep side-effect and dotted imports as observed.
			} else {
				nameToCheck := alias
				if nameToCheck == "" {
					nameToCheck = resolvedName
				}
				if !usedNames[nameToCheck] {
					continue
				}
			}
		}

		entry := importEntry{
			spec:     cloneImportSpec(spec),
			group:    a.groupFor(path, alias, projectName),
			path:     path,
			explicit: alias != "",
		}
		entry.spec.Doc = nil
		entries = append(entries, entry)
	}

	grouped := make(map[string][]importEntry)
	for _, entry := range entries {
		grouped[entry.group] = append(grouped[entry.group], entry)
	}

	for key := range grouped {
		sort.SliceStable(grouped[key], func(i, j int) bool {
			return grouped[key][i].path < grouped[key][j].path
		})
	}

	var out []*ast.ImportSpec
	for _, group := range a.order {
		items := grouped[group]
		if len(items) == 0 {
			continue
		}
		if a.cfg.separateNamed && group != "blanked" && group != "dotted" {
			var unnamed, named []importEntry
			for _, item := range items {
				if item.explicit {
					named = append(named, item)
				} else {
					unnamed = append(unnamed, item)
				}
			}
			if len(unnamed) > 0 {
				for _, item := range unnamed {
					out = append(out, item.spec)
				}
			}
			if len(named) > 0 {
				if len(out) > 0 {
					out = append(out, nil)
				}
				for _, item := range named {
					out = append(out, item.spec)
				}
			}
			if len(out) > 0 && group != a.lastNonEmptyGroup(grouped) {
				out = append(out, nil)
			}
			continue
		}
		for _, item := range items {
			out = append(out, item.spec)
		}
		if len(out) > 0 && group != a.lastNonEmptyGroup(grouped) {
			out = append(out, nil)
		}
	}

	for len(out) > 0 && out[len(out)-1] == nil {
		out = out[:len(out)-1]
	}

	return out, nil
}

func (a *app) lastNonEmptyGroup(grouped map[string][]importEntry) string {
	last := ""
	for _, group := range a.order {
		if len(grouped[group]) > 0 {
			last = group
		}
	}
	return last
}

func cloneImportSpec(spec *ast.ImportSpec) *ast.ImportSpec {
	out := &ast.ImportSpec{
		Path: &ast.BasicLit{
			Kind:  spec.Path.Kind,
			Value: spec.Path.Value,
		},
	}
	if spec.Name != nil {
		out.Name = ast.NewIdent(spec.Name.Name)
	}
	if spec.Comment != nil {
		out.Comment = &ast.CommentGroup{}
		for _, c := range spec.Comment.List {
			out.Comment.List = append(out.Comment.List, &ast.Comment{Text: c.Text})
		}
	}
	return out
}

func (a *app) groupFor(path, alias, projectName string) string {
	if alias == "_" && a.orderSet["blanked"] {
		return "blanked"
	}
	if alias == "." && a.orderSet["dotted"] {
		return "dotted"
	}
	if isStdImport(path) {
		return "std"
	}
	if matchesPrefix(path, projectName) {
		return "project"
	}
	for _, prefix := range a.companyPrefixes {
		if matchesPrefix(path, prefix) {
			return "company"
		}
	}
	return "general"
}

func matchesPrefix(path, prefix string) bool {
	if prefix == "" {
		return false
	}
	return path == prefix || strings.HasPrefix(path, prefix+"/")
}

func isStdImport(path string) bool {
	if path == "C" {
		return true
	}
	first := path
	if idx := strings.Index(path, "/"); idx >= 0 {
		first = path[:idx]
	}
	return !strings.Contains(first, ".")
}

var versionSuffixRe = regexp.MustCompile(`/v[0-9]+$`)

func versionAlias(path, resolvedName string) (string, bool) {
	if !versionSuffixRe.MatchString(path) {
		return "", false
	}
	if resolvedName == "" {
		return "", false
	}
	return resolvedName, true
}

func defaultImportName(path string) string {
	parts := strings.Split(path, "/")
	last := parts[len(parts)-1]
	if versionSuffixRe.MatchString(path) && len(parts) >= 2 {
		return parts[len(parts)-2]
	}
	return last
}

func (a *app) renderImportBlock(fset *token.FileSet, specs []*ast.ImportSpec) []byte {
	var buf bytes.Buffer
	buf.WriteString("import (\n")

	for i, spec := range specs {
		if spec == nil {
			buf.WriteString("\n")
			continue
		}

		var line bytes.Buffer
		_ = printer.Fprint(&line, fset, spec)
		buf.WriteString("\t")
		buf.WriteString(strings.TrimSpace(line.String()))
		buf.WriteByte('\n')

		if i == len(specs)-1 {
			continue
		}
	}

	buf.WriteString(")\n")
	return buf.Bytes()
}

func replaceImportBlock(data []byte, fset *token.FileSet, decls []*ast.GenDecl, block []byte) []byte {
	if len(decls) == 0 {
		return data
	}

	start := fset.Position(decls[0].Pos()).Offset
	end := fset.Position(decls[len(decls)-1].End()).Offset

	var out bytes.Buffer
	out.Write(data[:start])
	out.Write(block)
	out.Write(data[end:])
	return out.Bytes()
}

func (a *app) emitFileResult(info targetInfo, result fileResult) error {
	if a.cfg.listDiff {
		fmt.Println(mustAbs(result.path))
	}
	if result.changed {
		a.changedAny = true
	}

	switch a.cfg.output {
	case "file", "write":
		if !a.cfg.listDiff && result.changed {
			if err := os.WriteFile(result.path, result.formatted, 0o644); err != nil {
				return err
			}
		} else if a.cfg.output == "write" && a.cfg.listDiff && result.changed {
			if err := os.WriteFile(result.path, result.formatted, 0o644); err != nil {
				return err
			}
		}
	case "stdout":
		_, err := os.Stdout.Write(result.formatted)
		return err
	default:
		log.Printf("invalid output %q specified", a.cfg.output)
		return fmt.Errorf("invalid output")
	}

	return nil
}

func (a *app) emitDirectoryResult(result fileResult) error {
	if a.cfg.listDiff {
		if result.changed {
			fmt.Println(mustAbs(result.path))
		}
	} else if a.cfg.output == "stdout" {
		if _, err := os.Stdout.Write(result.formatted); err != nil {
			return err
		}
	} else if a.cfg.output == "file" || a.cfg.output == "write" {
		if result.changed {
			if err := os.WriteFile(result.path, result.formatted, 0o644); err != nil {
				return err
			}
		}
	} else {
		log.Printf("invalid output %q specified", a.cfg.output)
		return fmt.Errorf("invalid output")
	}

	if result.changed {
		a.changedAny = true
	}
	return nil
}

func mustAbs(path string) string {
	abs, err := filepath.Abs(path)
	if err != nil {
		return path
	}
	return abs
}

func (a *app) handleGoListError(output []byte) error {
	if len(output) > 0 {
		_, _ = io.Copy(os.Stderr, bytes.NewReader(output))
	}
	return fmt.Errorf("package has an errors")
}

